import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.O93z6AWZ.js";const m=JSON.parse('{"title":"Topic 2.1 — Urticaria (Dr May Day)","description":"","frontmatter":{"title":"Topic 2.1 — Urticaria (Dr May Day)"},"headers":[],"relativePath":"en/du_an/may_day.md","filePath":"en/du_an/may_day.md"}'),i={name:"en/du_an/may_day.md"};function n(s,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="topic-2-1-segmenting-and-measuring-wheals-from-skin-photos-to-support-urticaria-management" tabindex="-1">Topic 2.1: Segmenting and Measuring Wheals from Skin Photos to Support Urticaria Management <a class="header-anchor" href="#topic-2-1-segmenting-and-measuring-wheals-from-skin-photos-to-support-urticaria-management" aria-label="Permalink to &quot;Topic 2.1: Segmenting and Measuring Wheals from Skin Photos to Support Urticaria Management&quot;">​</a></h1><p><strong>Topic group:</strong> 2. Medical Imaging (Fundus/Dermatology) · <strong>Status:</strong> ⚠️ Small-scale literature (6 trial records) — needs expansion before formal use</p><div class="tip custom-block"><p class="custom-block-title">📥 Full documentation on GitHub</p><p>Raw data and detailed source code are kept <strong>Private</strong> on the department&#39;s GitHub repository (so students complete the work themselves). This page gives you the essential information to get started.</p></div><p>Read the <strong><a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a></strong> first.</p><hr><h2 id="_1-problem-statement" tabindex="-1">1. Problem statement <a class="header-anchor" href="#_1-problem-statement" aria-label="Permalink to &quot;1. Problem statement&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Research question</strong></td><td>Segment and measure the area/severity of wheals from skin photographs to support Urticaria severity assessment</td></tr><tr><td><strong>Input (X)</strong></td><td>Photo of the affected skin area, ideally with a size-reference object (ruler/color card)</td></tr><tr><td><strong>Output (Y)</strong></td><td>A wheal segmentation mask + area converted to cm², or a severity score (Urticaria Activity Score)</td></tr><tr><td><strong>Suggested dataset</strong></td><td>Self-collected with a reference object, or open-source dermoscopy datasets</td></tr><tr><td><strong>Specific challenge</strong></td><td>Hairy skin, lighting noise; converting pixels to real-world size (cm) for an accurate wheal area score</td></tr></tbody></table><hr><h2 id="_2-starter-literature-1-include-3-context-2-exclude" tabindex="-1">2. Starter literature (1 INCLUDE + 3 CONTEXT + 2 EXCLUDE) <a class="header-anchor" href="#_2-starter-literature-1-include-3-context-2-exclude" aria-label="Permalink to &quot;2. Starter literature (1 INCLUDE + 3 CONTEXT + 2 EXCLUDE)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Direct-literature-scarce topic</p><p>Only <strong>1 direct precedent</strong> was found for the computer-vision problem on urticaria — and it is itself hive counting/detection rather than pixel-level segmentation (Dice/IoU) as the research question asks. This is a sign of a <strong>genuine research gap</strong> — good as an opening argument (Introduction) for the team&#39;s report, but it also means the team will struggle to find ≥10 directly relevant papers and needs to broaden the search to other dermatology conditions using similar methods (skin-lesion area measurement in general).</p></div><h3 id="include-record" tabindex="-1">INCLUDE record <a class="header-anchor" href="#include-record" aria-label="Permalink to &quot;INCLUDE record&quot;">​</a></h3><p><strong><code>maccarthy2024auas</code></strong> — <em>Automatic Urticaria Activity Score: Deep Learning-Based Automatic Hive Counting for Urticaria Severity Assessment</em>, JID Innovations 2024 (doi: <a href="https://doi.org/10.1016/j.xjidi.2023.100218" target="_blank" rel="noreferrer">10.1016/j.xjidi.2023.100218</a>). Legit.Health-UAS-HiveNet model, 313 images labeled by 5 experts, Krippendorff alpha = 0.826 (hive counting) / 0.603 (severity grading).</p><div class="warning custom-block"><p class="custom-block-title">Lesson on literal vs. spirit of inclusion criteria</p><p>This paper is a <strong>counting/detection</strong> problem reporting <strong>Krippendorff alpha</strong> (inter-rater agreement) — not Dice/IoU as the inclusion criteria literally state. It was kept because it satisfies the broader outcome axis (&quot;Severity correlation&quot;) and is the closest evidence available. <strong>Lesson for students:</strong> when a paper nearly matches but doesn&#39;t 100% match the criteria&#39;s wording, don&#39;t unilaterally include or exclude it — document the conflict and let the committee/instructor decide.</p></div><h3 id="context-records-3" tabindex="-1">CONTEXT records (3) <a class="header-anchor" href="#context-records-3" aria-label="Permalink to &quot;CONTEXT records (3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Citekey</th><th>Reason for CONTEXT</th></tr></thead><tbody><tr><td><code>gomes2024deeplearning</code></td><td>Wrong population (Skin Prick Test, not chronic urticaria) but the closest technical precedent for wheal-size measurement (N=5,844 images, segmentation accuracy 85.88%)</td></tr><tr><td><code>choy2023systematic</code></td><td>Systematic review — introductory background, not included in the quantitative Evidence Matrix</td></tr><tr><td><code>pathania2023aiurticaria</code></td><td>Short commentary/opinion piece, no standalone segmentation data</td></tr></tbody></table><h3 id="exclude-records-2" tabindex="-1">EXCLUDE records (2) <a class="header-anchor" href="#exclude-records-2" aria-label="Permalink to &quot;EXCLUDE records (2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Citekey</th><th>Reason for EXCLUDE</th></tr></thead><tbody><tr><td><code>yang2025llmurticaria</code></td><td>Wrong intervention — evaluates an LLM chatbot answering text, no computer vision</td></tr><tr><td><code>unverified2024yolov8skin</code></td><td>Wrong focus + <strong>DOI could not be found</strong> via Crossref — not usable as evidence</td></tr></tbody></table><hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Follow the common 7-stage workflow / 15-week timeline (see the detailed template at <a href="/hmyt-book/en/du_an/roi_loan_nhip_tim">Topic 1.2 — Arrhythmia</a>). Specific notes:</p><ul><li><strong>gd1-proposal:</strong> because direct literature is scarce, the team needs to spend more time here broadening the search (dermoscopy in general, skin-lesion area measurement via CV) rather than only searching the exact keyword &quot;urticaria&quot;.</li><li><strong>gd2-dataset-eda:</strong> if self-collecting images, a size-reference object must be in every frame from the start (cannot be added later).</li><li><strong>gd3-preprocessing:</strong> normalize lighting/color, handle hair/fur noise, augmentation suited to realistic capture-angle variation.</li><li><strong>gd6-evaluation-xai:</strong> use Grad-CAM/U-Net segmentation maps as visual XAI evidence; cross-check automatic scores against expert assessment (as <code>maccarthy2024auas</code> did with Krippendorff alpha).</li></ul><hr><h2 id="_4-open-items-from-the-literature-report" tabindex="-1">4. Open items (from the literature report) <a class="header-anchor" href="#_4-open-items-from-the-literature-report" aria-label="Permalink to &quot;4. Open items (from the literature report)&quot;">​</a></h2><ol><li>This review pass found only 6 manually-searched records — students must invest significantly in expanded search to reach ≥10 papers; this is the most literature-scarce topic in the whole bank.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Every citation must match a real key in <code>.bib</code> with a DOI verified via the Crossref API (except <code>unverified2024yolov8skin</code> — correctly excluded for this exact reason).</p></div>',25)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
